import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadPollywoodData(){const e=readFileSync(resolve(__dirname,"../../pollywood-cinema-explorer/script.js"),"utf-8").replace(/document\.addEventListener\("app:route-changed"[\s\S]*$/,"");return new Function(e+"\nreturn { POLLYWOOD_CINEMA_INFO, POLLYWOOD_FILMS, POLLYWOOD_ARTISTS, POLLYWOOD_TIMELINE, POLLYWOOD_GALLERY, POLLYWOOD_REFERENCES };")()}describe("Pollywood Cinema Explorer — Data Integrity",()=>{let e;beforeAll(()=>{e=loadPollywoodData()}),describe("POLLYWOOD_CINEMA_INFO metadata",()=>{it("contains correct id and name",()=>{expect(e.POLLYWOOD_CINEMA_INFO.id).toBe("pollywood-cinema"),expect(e.POLLYWOOD_CINEMA_INFO.name).toContain("Pollywood")}),it("identifies correct language and region",()=>{expect(e.POLLYWOOD_CINEMA_INFO.language).toBe("Punjabi"),expect(e.POLLYWOOD_CINEMA_INFO.region).toContain("Punjab")}),it("references Eighth Schedule correctly",()=>{expect(e.POLLYWOOD_CINEMA_INFO.schedule).toContain("Eighth Schedule")}),it("has at least 3 cultural roots listed",()=>{expect(Array.isArray(e.POLLYWOOD_CINEMA_INFO.culturalRoots)).toBe(!0),expect(e.POLLYWOOD_CINEMA_INFO.culturalRoots.length).toBeGreaterThanOrEqual(3)})}),describe("POLLYWOOD_FILMS dataset",()=>{it("contains exactly 6 notable film entries",()=>{expect(Array.isArray(e.POLLYWOOD_FILMS)).toBe(!0),expect(e.POLLYWOOD_FILMS.length).toBe(6)}),it("every film entry has required fields: id, title, year, genre, significance",()=>{e.POLLYWOOD_FILMS.forEach((e,t)=>{expect(e,`Film ${t} missing id`).toHaveProperty("id"),expect(e,`Film ${t} missing title`).toHaveProperty("title"),expect(e,`Film ${t} missing year`).toHaveProperty("year"),expect(e,`Film ${t} missing genre`).toHaveProperty("genre"),expect(e,`Film ${t} missing significance`).toHaveProperty("significance"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.year).toBe("number")})}),it("first film is from the 1930s (pioneer era)",()=>{const t=e.POLLYWOOD_FILMS[0];expect(t.year).toBe(1935)}),it("films are in chronological order",()=>{for(let t=0;t<e.POLLYWOOD_FILMS.length-1;t++)expect(e.POLLYWOOD_FILMS[t].year).toBeLessThanOrEqual(e.POLLYWOOD_FILMS[t+1].year)})}),describe("POLLYWOOD_ARTISTS dataset",()=>{it("contains at least 4 pioneering artists",()=>{expect(Array.isArray(e.POLLYWOOD_ARTISTS)).toBe(!0),expect(e.POLLYWOOD_ARTISTS.length).toBeGreaterThanOrEqual(4)}),it("every artist has id, name, role, and contribution fields",()=>{e.POLLYWOOD_ARTISTS.forEach((e,t)=>{expect(e,`Artist ${t} missing id`).toHaveProperty("id"),expect(e,`Artist ${t} missing name`).toHaveProperty("name"),expect(e,`Artist ${t} missing role`).toHaveProperty("role"),expect(e,`Artist ${t} missing contribution`).toHaveProperty("contribution"),expect(typeof e.name).toBe("string"),expect(e.name.trim().length).toBeGreaterThan(0)})}),it("includes Diljit Dosanjh as a key artist",()=>{const t=e.POLLYWOOD_ARTISTS.find(e=>e.name.includes("Diljit Dosanjh"));expect(t).toBeDefined(),expect(t.role).toContain("Actor")})}),describe("POLLYWOOD_TIMELINE dataset",()=>{it("contains exactly 5 timeline eras",()=>{expect(Array.isArray(e.POLLYWOOD_TIMELINE)).toBe(!0),expect(e.POLLYWOOD_TIMELINE.length).toBe(5)}),it("every timeline entry has id, period, era, and description",()=>{e.POLLYWOOD_TIMELINE.forEach((e,t)=>{expect(e,`Timeline ${t} missing id`).toHaveProperty("id"),expect(e,`Timeline ${t} missing period`).toHaveProperty("period"),expect(e,`Timeline ${t} missing era`).toHaveProperty("era"),expect(e,`Timeline ${t} missing description`).toHaveProperty("description"),expect(typeof e.era).toBe("string"),expect(e.era.trim().length).toBeGreaterThan(0)})}),it("first era is the 1930s-1940s Lahore hub period",()=>{expect(e.POLLYWOOD_TIMELINE[0].period).toContain("1930")}),it("last era references global reach or modern resurgence",()=>{const t=e.POLLYWOOD_TIMELINE[e.POLLYWOOD_TIMELINE.length-1];expect(t.description).toMatch(/global|resurgence|crossover/i)})}),describe("POLLYWOOD_GALLERY dataset",()=>{it("has exactly 4 gallery items",()=>{expect(Array.isArray(e.POLLYWOOD_GALLERY)).toBe(!0),expect(e.POLLYWOOD_GALLERY.length).toBe(4)}),it("every gallery item has id, title, and subtitle",()=>{e.POLLYWOOD_GALLERY.forEach((e,t)=>{expect(e,`Gallery ${t} missing id`).toHaveProperty("id"),expect(e,`Gallery ${t} missing title`).toHaveProperty("title"),expect(e,`Gallery ${t} missing subtitle`).toHaveProperty("subtitle")})})}),describe("POLLYWOOD_REFERENCES dataset",()=>{it("contains at least 4 references",()=>{expect(Array.isArray(e.POLLYWOOD_REFERENCES)).toBe(!0),expect(e.POLLYWOOD_REFERENCES.length).toBeGreaterThanOrEqual(4)}),it("every reference has id, source, and title",()=>{e.POLLYWOOD_REFERENCES.forEach((e,t)=>{expect(e,`Reference ${t} missing id`).toHaveProperty("id"),expect(e,`Reference ${t} missing source`).toHaveProperty("source"),expect(e,`Reference ${t} missing title`).toHaveProperty("title")})}),it("includes NFAI as a reference source",()=>{const t=e.POLLYWOOD_REFERENCES.find(e=>e.source.includes("NFAI")||e.source.includes("National Film Archive"));expect(t).toBeDefined()})})});